import{_ as d,o as e,c as a,a3 as o}from"./chunks/framework.DeRSg1wr.js";const _=JSON.parse('{"title":"SpanId的生成规则","description":"解释 TLog 层级 spanId、客户端当前 span 与下游子 span，以及并发序号规则。","frontmatter":{"title":"SpanId的生成规则","date":"2022-09-12T13:51:50.000Z","permalink":"/pages/595a3c/","description":"解释 TLog 层级 spanId、客户端当前 span 与下游子 span，以及并发序号规则。"},"headers":[],"relativePath":"pages/595a3c/index.md","filePath":"10.文档/100.SpanId的生成规则.md"}'),s={name:"pages/595a3c/index.md"};function n(p,t,c,r,i,l){return e(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="spanid的生成规则" tabindex="-1">SpanId的生成规则 <a class="header-anchor" href="#spanid的生成规则" aria-label="Permalink to &quot;SpanId的生成规则&quot;">​</a></h1><p>默认标签为 <code>&lt;$spanId&gt;&lt;$traceId&gt;</code>。traceId 用来关联同一个请求，spanId 表示当前节点在调用树中的位置。</p><p>没有上游 spanId 时，入口使用根 span <code>0</code>。每次通过 TLog 传播器向下游发起调用，会生成“当前 span + 自增序号”的子 span。</p><table tabindex="0"><thead><tr><th>调用</th><th>本端当前 span</th><th>写给下游的 span</th><th>下游入口使用的 span</th></tr></thead><tbody><tr><td>A → B</td><td><code>0</code></td><td><code>0.1</code></td><td><code>0.1</code></td></tr><tr><td>A → C</td><td><code>0</code></td><td><code>0.2</code></td><td><code>0.2</code></td></tr><tr><td>A → D</td><td><code>0</code></td><td><code>0.3</code></td><td><code>0.3</code></td></tr><tr><td>C → E</td><td><code>0.2</code></td><td><code>0.2.1</code></td><td><code>0.2.1</code></td></tr><tr><td>C → F</td><td><code>0.2</code></td><td><code>0.2.2</code></td><td><code>0.2.2</code></td></tr></tbody></table><p><strong>发起调用不会把 A 自己的当前 span 改成子 span。</strong> A 在调用前后的普通业务日志仍是 <code>0</code>，B 的入口日志才是 <code>0.1</code>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;0&gt;&lt;demo-request-001&gt; A 调用 B</span></span>
<span class="line"><span>&lt;0.1&gt;&lt;demo-request-001&gt; B 处理请求</span></span>
<span class="line"><span>&lt;0&gt;&lt;demo-request-001&gt; A 收到 B 的结果</span></span></code></pre></div><h2 id="异步与并发" tabindex="-1">异步与并发 <a class="header-anchor" href="#异步与并发" aria-label="Permalink to &quot;异步与并发&quot;">​</a></h2><p>同一请求通过受支持的传播方式切换线程时，保留当前 span，并共享其原子序号计数器。不同并发调用会获得不同子序号，但序号不承诺与业务完成顺序一致。请求结束后会清理当前 span 和计数器。</p><p>普通 WebFlux 入口保留原始请求头，首个 WebClient 出站为 <code>0.1</code>。Gateway 的转发会生成子 span，因此再经过下游服务继续调用时，层级可能为 <code>0.1.1</code>。</p><p>这不是 W3C 的 16 位十六进制 span-id，也不表示 TLog 会自动导出整棵追踪树。只覆盖已接入并正确传播的调用边；完整链路检索仍由日志系统承担。</p>`,10)])])}const g=d(s,[["render",n]]);export{_ as __pageData,g as default};
